// Validation errors displayed raw keys ("errors.validation.invalid_format") because the
// namespace generated by the server (ValidationError) and client (zod-bridge) was missing
// from every default bundle, and DefaultField did not pass issue.params to t(), leaving
// placeholders such as {minimum} uninterpolated.
import { describe, expect, test } from "bun:test";
import type { FieldIssue } from "../../headless/index.ts";
import { defaultPrimitives } from "../primitives/index.tsx";
import { render } from "./test-utils.tsx";

function renderFieldWithIssues(issues: readonly FieldIssue[]) {
  const { Field } = defaultPrimitives;
  return render(
    <Field id="f" label="Feld" issues={issues} testId="field-under-test">
      <input id="f" />
    </Field>,
  );
}

describe("DefaultField / errors.validation.* i18n", () => {
  test("invalid_format zeigt übersetzten Text statt rohem Key", () => {
    const view = renderFieldWithIssues([
      { path: "startsAt", code: "invalid_format", i18nKey: "errors.validation.invalid_format" },
    ]);
    expect(view.container.textContent).not.toContain("errors.validation");
    expect(view.container.textContent).toContain("Invalid format.");
  });

  test("invalid_format with a known format shows that format's example", () => {
    const view = renderFieldWithIssues([
      {
        path: "email",
        code: "invalid_format",
        i18nKey: "errors.validation.invalid_format",
        params: { format: "email" },
      },
    ]);
    expect(view.container.textContent).toContain("name@example.com");
  });

  test("invalid_format with an unknown format keeps the generic text", () => {
    const view = renderFieldWithIssues([
      {
        path: "code",
        code: "invalid_format",
        i18nKey: "errors.validation.invalid_format",
        params: { format: "regex" },
      },
    ]);
    expect(view.container.textContent).toContain("Invalid format.");
  });

  test("the error text is linked to the control via aria-describedby", () => {
    const { Field, Input } = defaultPrimitives;
    const view = render(
      <Field
        id="mail"
        label="Mail"
        issues={[{ path: "mail", code: "custom", i18nKey: "errors.validation.custom" }]}
      >
        <Input id="mail" name="mail" kind="text" value="" onChange={() => {}} hasError />
      </Field>,
    );
    const input = view.container.querySelector("input") as HTMLInputElement;
    const errorId = input.getAttribute("aria-describedby");
    expect(errorId).toBeTruthy();
    expect(view.container.querySelector(`[id="${errorId}"]`)?.textContent).toContain(
      "Invalid value.",
    );
  });

  test("too_small interpoliert {minimum} aus issue.params", () => {
    const view = renderFieldWithIssues([
      {
        path: "name",
        code: "too_small",
        i18nKey: "errors.validation.too_small",
        params: { minimum: 3 },
      },
    ]);
    expect(view.container.textContent).not.toContain("errors.validation");
    expect(view.container.textContent).not.toContain("{minimum}");
    expect(view.container.textContent).toContain("minimum: 3");
  });

  test("alle Server-/Zod-Codes sind in beiden Default-Bundles übersetzt", async () => {
    const { kumikoDefaultTranslations } = await import("../../index.ts");
    const codes = [
      "invalid_type",
      "too_small",
      "too_big",
      "invalid_format",
      "not_multiple_of",
      "unrecognized_keys",
      "invalid_union",
      "invalid_key",
      "invalid_element",
      "invalid_value",
      "custom",
      "unexpected_field",
      "out_of_bounds",
      "invalid_option",
      "failed",
    ];
    const { localeDeBundle } = await import("@cosmicdrift/kumiko-locale-de");
    for (const code of codes) {
      expect(kumikoDefaultTranslations["en"]?.[`errors.validation.${code}`]).toBeString();
      expect(localeDeBundle[`errors.validation.${code}`]).toBeString();
    }
  });
});
